--- index.html
+++ index.html
@@ -20,4 +20,26 @@
 <div class="mobile-controls"><div class="joy" id="joy"></div><div class="lookpad" id="lookpad"></div><div class="actions"><button id="mineBtn">⛏<span>MINERAR</span></button><button id="placeBtn">▧<span>COLOCAR</span></button><button id="jumpBtn">↑<span>PULAR</span></button></div></div>
 </div></div>
 <div class="overlay" id="intro"><section class="panel"><div class="eyebrow">A FRONTEIRA ESQUECIDA · CAPÍTULO I</div><h1>FROST<br><span>& FLAME</span></h1><p>Uma terra selvagem de gelo e fogo. Explore ruínas antigas, reúna recursos e enfrente o dragão que desperta nas montanhas.</p><div class="quest"><div class="egg">🐉</div><div><b>Caçada ao dragão de gelo</b><small>Explore, sobreviva e prove seu valor.</small></div></div><button class="play" id="start">ENTRAR NA FRONTEIRA &nbsp; →</button><div class="foot">Mundo voxel · Sobrevivência · A lenda é sua para escrever</div></section></div>
 <script>
+(()=>{
+const canvas=document.getElementById('view'),ctx=canvas.getContext('2d',{alpha:false}),$=s=>document.querySelector(s);
+let W=0,H=0,dpr=1;function resize(){dpr=Math.min(devicePixelRatio||1,1.5);W=innerWidth;H=innerHeight;canvas.width=W*dpr;canvas.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',resize);resize();
+const colors={grass:'#6f9060',dirt:'#795e4e',stone:'#777f82',snow:'#dce7df',ice:'#83c8d1',wood:'#816042',leaves:'#406757',crystal:'#8ce7e5',obsidian:'#453d56',sand:'#b8a47a',fire:'#df7946'};
+const blocks=new Map(),key=(x,y,z)=>`${x},${y},${z}`,put=(x,y,z,t)=>blocks.set(key(x,y,z),{x,y,z,t}),get=(x,y,z)=>blocks.get(key(x,y,z));
+function surface(x,z){return Math.max(1,Math.floor(2+Math.sin(x*.31)*.72+Math.cos(z*.27)*.62+Math.sin((x+z)*.17)*.7+Math.sin(x*.11-z*.09)*.8))}
+for(let x=-30;x<=30;x++)for(let z=-30;z<=30;z++){let h=surface(x,z),special=Math.sin(x*.22+z*.15);for(let y=0;y<=h;y++){let t=y===h?(special>.68?'snow':'grass'):y===h-1?'dirt':'stone';put(x,y,z,t)}}
+// Pine trees, frozen crystal clusters, and a half-buried ruin.
+function tree(x,z){let y=surface(x,z)+1;for(let i=0;i<4;i++)put(x,y+i,z,'wood');for(let dy=2;dy<6;dy++){let r=dy===5?0:dy<4?2:1;for(let dx=-r;dx<=r;dx++)for(let dz=-r;dz<=r;dz++)if(Math.abs(dx)+Math.abs(dz)<r*2+1&&Math.random()>.08)put(x+dx,y+dy,z+dz,'leaves')}}
+for(const [x,z] of [[-8,1],[-12,8],[9,0],[13,7],[-15,-4],[17,-3],[7,19],[-4,17],[21,12],[-20,15]])tree(x,z);
+for(const [x,z] of [[-6,9],[7,6],[12,14],[-16,4],[19,4]]){let y=surface(x,z)+1;put(x,y,z,'crystal');put(x,y+1,z,'ice');put(x+1,y,z,'ice')}
+for(let x=-2;x<=2;x++)for(let z=8;z<=11;z++){let y=surface(x,z)+1;if(Math.abs(x)===2||z===8||z===11)put(x,y,z,'stone');if(z===8&&x===0)put(x,y,z,'obsidian');}
+const player={x:0,z:-8,y:surface(0,-8)+.02,vx:0,vy:0,vz:0,yaw:0,pitch:-.035,hp:5,ground:true};let dragon={x:3,z:11,y:surface(3,11)+5.7,hp:100,alive:true,phase:0,hit:0};
+let started=false,keys={},selected=0,inventory=[{t:'stone',n:24},{t:'wood',n:12},{t:'ice',n:9},{t:'crystal',n:4},{t:'obsidian',n:3},{t:'fire',n:2}],lastHit=null,toastTimer=0,attackCooldown=0,fireballs=[],time=0,damageFlash=0;
+const slots=[['🪨','Pedra','stone'],['🪵','Madeira','wood'],['🧊','Gelo','ice'],['💠','Cristal','crystal'],['⬛','Obsidiana','obsidian'],['🔥','Fogo','fire']];
+function buildHotbar(){const bar=$('#hotbar');bar.innerHTML='';slots.forEach((s,i)=>{let el=document.createElement('div');el.className='slot'+(i===selected?' active':'');el.innerHTML=`<kbd>${i+1}</kbd><span class="icon">${s[0]}</span><small>${s[1]}</small><em>${inventory[i].n}</em>`;bar.appendChild(el)})}buildHotbar();
+function notify(text){const e=$('#toast');e.textContent=text;e.classList.add('show');toastTimer=2.2}
+function coords(wx,wy,wz){let dx=wx-player.x,dz=wz-player.z,sy=Math.sin(player.yaw),cy=Math.cos(player.yaw),sp=Math.sin(player.pitch),cp=Math.cos(player.pitch),forward=dx*sy+dz*cy;return{x:dx*cy-dz*sy,y:(wy-(player.y+1.55))*cp-forward*sp,z:forward*cp+(wy-(player.y+1.55))*sp}}
+const focal=()=>Math.min(W,H)*.92;
+function proj(p){return{x:W/2+p.x*focal()/p.z,y:H*.51-p.y*focal()/p.z}}
+function cubeFaces(b){let x=b.x,y=b.y,z=b.z,verts=[[x,y,z],[x+1,y,z],[x+1,y+1,z],[x,y+1,z],[x,y,z+1],[x+1,y,z+1],[x+1,y+1,z+1],[x,y+1,z+1]],faces=[[0,1,2,3,[0,-1,0],'top'],[4,7,6,5,[0,1,0],'bottom'],[0,4,5,1,[0,0,-1],'front'],[1,5,6,2,[1,0,0],'right'],[4,0,3,7,[-1,0,0],'left'],[3,2,6,7,[0,0,1],'back']];let center=[x+.5,y+.5,z+.5],toCam=[player.x-center[0],player.y+1.55-center[1],player.z-center[2]];let tone={top:1.13,bottom:.58,front:.91,right:.78,left:1.04,back:.84};let out=[];for(let f of faces){if(f[4][0]*toCam[0]+f[4][1]*toCam[1]+f[4][2]*toCam[2]<=0)continue;let ps=f.slice(0,4).map(i=>coords(...verts[i]));if(ps.some(p=>p.z<.15))continue;out.push({ps,depth:ps.reduce((a,p)=>a+p.z,0)/4,color:b.t,shade:tone[f[5]]})}return out}
+function tint(hex,k){let n=parseInt(hex.slice(1),16),r=Math.min(255,((n>>16)&255)*k),g=Math.min(255,((n>>8)&255)*k),b=Math.min(255,(n&255)*k);return`rgb(${r|0},${g|0},${b|0})`}

