function actorPieces(){let out=[];for(const m of mobs){if(!m.alive)continue;let bob=Math.sin(time*3+m.phase)*.05,x=m.x,y=surface(Math.floor(m.x),Math.floor(m.z))+.2+bob,z=m.z,s=m.type==='urso'?.8:.55;let fur=m.type==='urso'?'#765945':'#84928b';const box=(ox,oy,oz,size,color)=>{let b={x:x+ox-size/2,y:y+oy-size/2,z:z+oz-size/2,s:size,t:color};out.push(...cubeFaces(b))};box(0,.35,0,s,fur);box(0,.43,-s*.55,s*.48,fur);box(-.12,.49,-s*.79,.07,'#201e20');box(.12,.49,-s*.79,.07,'#201e20');for(const side of [-1,1])box(side*s*.27,.09,0,.17,fur);if(m.hit>0){for(let f of out)f.alpha=.55}}
return out}
function buildWorldForContent(){for(const c of chests){let y=surface(c.x,c.z)+1;put(c.x,y,c.z,'gold_ore')}for(let i=0;i<13;i++){let x=(i*17%53)-26,z=(i*29%53)-26;if(Math.hypot(x,z)>9)put(x,surface(x,z)+1,z,'coal_ore')}}buildWorldForContent();
const panel=$('#contentPanel'),panelTitle=$('#panelTitle'),panelBody=$('#panelBody'),panelTabs=$('#panelTabs');let activePanel='bag';
function openPanel(which='bag'){activePanel=which;started=true;document.exitPointerLock?.();panel.classList.add('open');drawPanel(which)}function closePanel(){panel.classList.remove('open');if(started&&!('ontouchstart'in window))canvas.requestPointerLock?.()}
function drawPanel(which){activePanel=which;const titles={bag:'MOCHILA & EQUIPAMENTO',craft:'OFÍCIO & RECEITAS',quests:'DIÁRIO DE AVENTURA',map:'MAPA DA FRONTEIRA',codex:'BESTIÁRIO & CONTROLES',pause:'JOGO PAUSADO'};panelTitle.textContent=titles[which]||'MOCHILA';let tabs=[['bag','Mochila'],['craft','Ofício'],['quests','Missões'],['map','Mapa'],['codex','Guia']];panelTabs.innerHTML=tabs.map(([id,n])=>`<button class="tab-button ${which===id?'active':''}" data-panel="${id}">${n}</button>`).join('');panelTabs.querySelectorAll('button').forEach(b=>b.onclick=()=>drawPanel(b.dataset.panel));
if(which==='bag'){let all={...bag};panelBody.innerHTML=`<div class="action-card"><b>Equipamento:</b> ${itemInfo[weapon]?.[0]||'👊'} ${itemInfo[weapon]?.[1]||'Punhos'} &nbsp;·&nbsp; 🛡 Armadura ${armor?armor+'%':'nenhuma'} &nbsp;·&nbsp; 🍗 Fome ${Math.ceil(food)}/20<br>Armas criadas aparecem aqui para equipar. Alimentos e poções: clique para usar.</div><div class="inventory-grid" style="margin-top:12px">${Object.keys(itemInfo).filter(id=>(all[id]||0)>0).map(id=>`<div class="item-card"><span class="big">${itemInfo[id][0]}</span><div><strong>${itemInfo[id][1]} × ${all[id]}</strong><small>${itemInfo[id][2]}</small>${['wood_sword','ice_sword','bow'].includes(id)?`<button data-equip="${id}">${weapon===id?'Equipado':'Equipar'}</button>`:''}${id==='bread'||id==='potion'?`<button data-use="${id}">Usar</button>`:''}</div></div>`).join('')}</div>`;
panelBody.querySelectorAll('[data-equip]').forEach(b=>b.onclick=()=>{weapon=b.dataset.equip;notify(`${itemInfo[weapon][1]} equipada`);drawPanel('bag')});panelBody.querySelectorAll('[data-use]').forEach(b=>b.onclick=()=>consume(b.dataset.use));}
if(which==='craft'){panelBody.innerHTML=`<div class="action-card">Materiais: ${Object.entries(bag).filter(([,n])=>n>0).map(([id,n])=>`${itemInfo[id]?.[0]||'•'} ${itemInfo[id]?.[1]||id} ${n}`).join(' · ')||'nenhum'}</div><div class="recipe-grid" style="margin-top:12px">${recipes.map(r=>`<div class="recipe"><div><strong>${r.icon} ${r.name}</strong><small>${r.kind} · ${r.desc}</small></div><small>Requer: ${Object.entries(r.cost).map(([id,n])=>`${itemInfo[id]?.[1]||id} ×${n}`).join(', ')}</small><button data-craft="${r.id}">${canCraft(r)?'CRIAR':'FALTAM MATERIAIS'}</button></div>`).join('')}</div>`;panelBody.querySelectorAll('[data-craft]').forEach(b=>b.onclick=()=>craft(b.dataset.craft));}
if(which==='quests'){let qs=[['Primeiros passos',`Colete cristais de gelo: ${bag.crystal||0}/5`,(bag.crystal||0)>=5],['Arme-se','Crie uma arma de verdade na bancada improvisada',!!crafted.wood_sword||!!crafted.ice_sword],['Ecos do passado','Encontre as ruínas antigas ao norte',discovered.ruins],['Sobrevivente','Derrote 3 criaturas da tundra',kills>=3],['Caçador de relíquias','Abra os 4 baús da fronteira',openedChests>=4],['Lenda da fronteira','Derrote o dragão de gelo',!dragon.alive]];panelBody.innerHTML=`<div class="quest-grid">${qs.map(q=>`<div class="quest-card ${q[2]?'done':''}"><strong>${q[2]?'✓':'◇'} ${q[0]}</strong><small>${q[1]}</small></div>`).join('')}</div><div class="action-card">Progresso: ${qs.filter(q=>q[2]).length}/${qs.length} · Nível ${level} · ${kills} criaturas derrotadas. Complete missões para avançar na história.</div>`}
if(which==='map'){panelBody.innerHTML=`<div class="map-card"><div class="map-grid"></div>${landmarks.map(l=>`<span class="map-pin" style="left:${50+l.x/60*48}%;top:${50-l.z/60*42}%" title="${l.name}">${l.icon}</span>`).join('')}<span class="map-pin" style="left:${50+player.x/60*48}%;top:${50-player.z/60*42}%">🧍</span><span class="map-pin" style="left:${50+dragon.x/60*48}%;top:${50-dragon.z/60*42}%">${dragon.alive?'🐉':'🏆'}</span></div><div class="map-legend">🧍 Você · 🐉 Dragão · 🏛 Ruínas · 🏘 Aldeia · 🕳 Gruta · 🔷 Santuário</div><div class="action-card">Coordenadas: ${Math.round(player.x)}, ${Math.round(player.z)} · Região: ${biomeName()}<br>O norte fica no topo do mapa. Explore os pontos marcados para encontrar baús e recursos.</div>`}
if(which==='codex'){panelBody.innerHTML=`<div class="codex"><h3>📖 Bestiário</h3><b>Dragão de gelo</b> — Antigo guardião das ruínas. Mantenha distância dos projéteis gelados. A lâmina glacial causa dano aumentado.<br><b>Lobo da tundra</b> — Rápido e territorial; derruba pele e couro.<br><b>Urso das cavernas</b> — Resistente e perigoso. Prefira arco e terreno elevado.<br><h3>🎮 Controles</h3>WASD mover · Mouse olhar · Espaço pular · Clique atacar/minerar · Botão direito construir · E interagir · I mochila · C ofício · J diário · M mapa · Q consumir cura · 1–6 blocos · Esc pausar.<br><h3>🌎 Regiões</h3>Tundra antiga (centro), bosque boreal (leste), gruta da prata (oeste), aldeia Pinhal (noroeste) e ruínas congeladas (norte).<br><h3>💾 Sobrevivência</h3>O mundo salva automaticamente neste navegador. Minere veios metálicos, cace animais, abra baús e fabrique equipamento antes de desafiar o dragão.</div><button id="resetSave" style="margin-top:14px">REINICIAR MUNDO SALVO</button>`;$('#resetSave').onclick=()=>{if(confirm('Apagar seu progresso e reiniciar a fronteira?')){localStorage.removeItem('frost-flame-save');location.reload()}}}
if(which==='pause'){panelBody.innerHTML=`<div class="action-card"><h3>Jogo pausado</h3>Seu progresso é salvo automaticamente. Continue explorando ou reinicie para começar uma nova aventura.</div><div class="tabs"><button id="resumeGame">CONTINUAR AVENTURA</button><button id="saveGame">SALVAR AGORA</button></div>`;$('#resumeGame').onclick=closePanel;$('#saveGame').onclick=()=>{saveGame();notify('Mundo salvo!')}}}
function canCraft(r){return Object.entries(r.cost).every(([id,n])=>(bag[id]||0)>=n)}
function craft(id){let r=recipes.find(x=>x.id===id);if(!r||!canCraft(r))return notify('Ainda faltam materiais');for(const [item,n] of Object.entries(r.cost))spend(item,n);let product=id==='leather_armor'||id==='iron_armor'?null:id==='leather_armor'||id==='iron_armor'?null:id;let qty=r.qty||1;if(product)addResource(product,qty);if(id==='leather_armor')armor=25;if(id==='iron_armor')armor=50;if(['wood_sword','ice_sword','bow'].includes(id)){weapon=id;crafted[id]=true}if(id==='leather_armor'||id==='iron_armor')crafted.armor=true;else crafted[id]=true;gainXP(15);notify(`${r.name} criado!`);drawPanel('craft')}
